import jetbrains.buildServer.configs.kotlin.*
import jetbrains.buildServer.configs.kotlin.buildFeatures.XmlReport
import jetbrains.buildServer.configs.kotlin.buildFeatures.xmlReport
import jetbrains.buildServer.configs.kotlin.buildSteps.script
import jetbrains.buildServer.configs.kotlin.triggers.vcs
import jetbrains.buildServer.configs.kotlin.vcs.GitVcsRoot

/*
 * jenkinsci/configuration-as-code-plugin on TeamCity, generated by the migration factory.
 * Source of truth for the mapping: work/design/jenkinsci__configuration-as-code-plugin.md
 *
 * Source CI: Jenkinsfile ->
 *   buildPlugin(useContainerAgent: true, forkCount: '0.5C', timeout: 360,
 *               configurations: [[platform: 'linux', jdk: 25], [platform: 'windows', jdk: 21]])
 * plus two GitHub Actions workflows (cd.yaml, jenkins-security-scan.yml), mirrored here as PAUSED configs.
 */

version = "2025.11"

project {
    description = "Migrated from ci.jenkins.io buildPlugin() + GitHub Actions; fork arokhin/configuration-as-code-plugin mirrors upstream master"

    vcsRoot(Fork)

    buildType(BuildLinuxJdk25)
    buildType(BuildWindowsJdk21)
    buildType(All)

    buildType(LaunchableRecordPaused)
    buildType(PublishIncrementalsPaused)
    buildType(ContinuousDeliveryPaused)
    buildType(SecurityScanPaused)

    buildTypesOrder = listOf(
        All, BuildLinuxJdk25, BuildWindowsJdk21,
        LaunchableRecordPaused, PublishIncrementalsPaused, ContinuousDeliveryPaused, SecurityScanPaused
    )
}

// The GitHub App connection PROJECT_EXT_66 ("TeamCity - demo.teamcity.com", on _Root) issues the token.
// Its tokenId only exists after `teamcity project connection authorize PROJECT_EXT_66`, so it arrives as a
// Versioned Settings DSL context parameter, never as a literal here (Lesson 9). The token ID is a
// reference, not a secret. Until it's set, the root falls back to anonymous read: the fork is public.
object Ctx {
    val githubTokenId: String get() = DslContext.getParameter("githubTokenId", "")
}

object Fork : GitVcsRoot({
    name = "arokhin/configuration-as-code-plugin (fork, master)"
    url = "https://github.com/arokhin/configuration-as-code-plugin.git"
    branch = "refs/heads/master"
    branchSpec = "+:refs/heads/master"
    if (Ctx.githubTokenId.isNotBlank()) {
        authMethod = token {
            userName = "oauth2"
            tokenId = Ctx.githubTokenId
        }
    } else {
        authMethod = anonymous()
    }
})

object Cell {
    // Shared by both cells. These mirror buildPlugin()'s mvn invocation from
    // jenkins-infra/pipeline-library vars/buildPlugin.groovy.
    // - Script steps, not the Maven runner: the runner may rewrite or strip args such as -P-consume-incrementals and
    //   -Dset.changelist (Lesson 3), and literal parity with buildPlugin() is the point.
    // - -Dmaven.test.failure.ignore: Maven exits 0 and the JUnit XML import below fails the build on any failed test.
    //   That reproduces buildPlugin()'s failFast "There were test failures; halting early" without double-handling.
    // - The checkstyle/spotbugs/pmd *.fail* = false flags match the source. The analysis is REPORT-ONLY by decision
    //   (2026-11-10), so the XML report import below has no failure conditions attached.
    const val MVN_ARGS =
        "-B -ntp --update-snapshots -Dmaven.repo.local=\"%tcmf.m2repo%\" " +
        "-Dmaven.test.failure.ignore -Dspotbugs.failOnError=false " +
        "-Dcheckstyle.failOnViolation=false -Dcheckstyle.failsOnError=false -Dpmd.failOnViolation=false"

    fun cellCommon(bt: BuildType, jdkEnvParam: String, cpuCount: Int, osFamily: String) = bt.apply {
        vcs {
            root(Fork)
            // git-changelist-maven-extension (.mvn/extensions.xml) derives the version from the commit count and hash.
            // It needs the real full history and a .git dir, so: agent-side checkout, no shallow clone. A server-side
            // checkout has no .git, and shallow would give a wrong or failing version.
            checkoutMode = CheckoutMode.ON_AGENT
            // Mirrors buildPlugin()'s `git clean -xffd` before each build.
            cleanCheckout = true
        }

        params {
            // A per-build local repo, like buildPlugin()'s `pwd tmp`/m2repo. Stateless by design (Lesson 7):
            // nothing is assumed to survive between builds or between cells.
            param("tcmf.m2repo", "%system.teamcity.build.tempDir%/m2repo")
            param("env.JAVA_HOME", "%$jdkEnvParam%")
        }

        requirements {
            // These parameter names were copied verbatim from the 2026-11-10 agent probe (Lesson 4: a typo here
            // silently makes every agent incompatible).
            equals("teamcity.agent.jvm.os.family", osFamily)
            exists(jdkEnvParam)
            // The Default pool is a set of discrete EC2 tiers: Small c5d.large 2 CPU / 3.7 GB, Medium c5d.xlarge
            // 4 CPU / 7.6 GB, Large c5d.2xlarge 8 CPU / 15 GB; Windows is Large only. cpuCount alone selects the tier,
            // so there is deliberately no memory requirement: it would be inert (Lesson 11).
            equals("teamcity.agent.hardware.cpuCount", cpuCount.toString())
        }

        failureConditions {
            // The Jenkinsfile asks for timeout: 360, but buildPlugin() clamps anything above 180 down to 180
            // ("lowering to 180 to avoid ... resource abusive consumption"). 180 is the real source budget per cell.
            executionTimeoutMin = 180
        }

        features {
            xmlReport {
                reportType = XmlReport.XmlReportType.JUNIT
                rules = "+:**/target/surefire-reports/TEST-*.xml"
                verbose = false
            }
        }
    }

    fun staticAnalysisReports(bt: BuildType) = bt.apply {
        // Report-only stand-in for warnings-ng (java, javadoc, checkstyle, spotbugs, pmd, cpd) on the first cell.
        // These have no failure conditions on purpose; see the decision log in the design doc.
        // Not reproduced: the ESLint and open-task scanners (the repo has no ESLint config, and the open-task scanner has
        // no TeamCity equivalent), listed as parity gaps in the design doc.
        features {
            xmlReport {
                reportType = XmlReport.XmlReportType.CHECKSTYLE
                rules = "+:**/target/checkstyle-result.xml"
            }
            xmlReport {
                reportType = XmlReport.XmlReportType.FINDBUGS
                rules = "+:**/target/spotbugsXml.xml"
            }
            xmlReport {
                reportType = XmlReport.XmlReportType.PMD
                rules = "+:**/target/pmd.xml"
            }
            xmlReport {
                reportType = XmlReport.XmlReportType.PMD_CPD
                rules = "+:**/target/cpd.xml"
            }
        }
    }
}

object BuildLinuxJdk25 : BuildType({
    name = "Build (linux, JDK 25)"
    description = "buildPlugin() cell 1 of 2: [platform: 'linux', jdk: 25]. This is the source's 'first cell': coverage, static analysis, incrementals"

    // Pass-1 sizing: Medium tier (4 CPU / 7.6 GB). Evidence: the source runs this cell on a ci.jenkins.io
    // container agent, and forkCount=0.5C gives 2 concurrent JenkinsRule JVM forks on 4 CPUs. That's the
    // migration brief's pass-1 guess. Pass 2 refines this from TeamCity's built-in per-build CPU/memory stats.
    Cell.cellCommon(this, jdkEnvParam = "env.JDK_25_0", cpuCount = 4, osFamily = "Linux")
    Cell.staticAnalysisReports(this)

    artifactRules = """
        +:plugin/target/*.hpi
        +:changelist.txt
        +:incrementals/** => incrementals.zip
        +:plugin/target/site/jacoco/** => coverage-jacoco.zip
    """.trimIndent()

    steps {
        script {
            name = "mvn clean install (buildPlugin parity, first cell)"
            scriptContent = """
                set -eu
                # -Penable-jacoco: buildPlugin() enables coverage on Unix cells only.
                # help:evaluate ... -Doutput=changelist.txt: buildPlugin() captures the changelist on the first cell, for incrementals.
                "%teamcity.tool.maven3_9%/bin/mvn" ${Cell.MVN_ARGS} -Penable-jacoco \
                  -Dset.changelist help:evaluate -Dexpression=changelist -Doutput=changelist.txt \
                  -P-consume-incrementals -DforkCount=0.5C clean install
            """.trimIndent()
        }
        script {
            name = "Collect incrementals artifacts from the per-build m2repo"
            // buildPlugin() archives **/*<changelist>/*<changelist>* from m2repo for maybePublishIncrementals().
            // They're published as an artifact for the paused PublishIncrementals config (snapshot + artifact dep).
            scriptContent = """
                set -eu
                CL=${'$'}(cat changelist.txt)
                rm -rf incrementals && mkdir -p incrementals
                cd "%tcmf.m2repo%"
                find . -type f -path "*${'$'}CL/*${'$'}CL*" -exec cp --parents {} "%teamcity.build.checkoutDir%/incrementals/" \;
            """.trimIndent()
        }
    }
})

object BuildWindowsJdk21 : BuildType({
    name = "Build (windows, JDK 21)"
    description = "buildPlugin() cell 2 of 2: [platform: 'windows', jdk: 21]. Tests and packaging only, as in the source"

    // Pass-1 sizing: Large (8 CPU / 15.9 GB). This isn't a choice: Windows-Server-2022-Large is the only Windows tier in
    // the Default pool (probe 2026-11-10). With forkCount=0.5C that's 4 forks.
    Cell.cellCommon(this, jdkEnvParam = "env.JDK_21_0", cpuCount = 8, osFamily = "Windows")

    steps {
        script {
            name = "mvn clean install (buildPlugin parity)"
            // No -Penable-jacoco: buildPlugin() enables it on Unix only. The per-build m2repo sits under the agent's
            // temp dir (C:\BuildAgent\temp\...), which keeps paths short. Surefire's default manifest-only jar
            // keeps the forked test JVM's command line under the Windows length limit.
            scriptContent = """
                call "%teamcity.tool.maven3_9%\bin\mvn.cmd" ${Cell.MVN_ARGS} -P-consume-incrementals -DforkCount=0.5C clean install
                exit /b %%ERRORLEVEL%%
            """.trimIndent()
        }
    }
})

object All : BuildType({
    name = "All (ci.jenkins.io parity)"
    description = "Composite of both buildPlugin() cells. Green here is the equivalent of the continuous-integration/jenkins/branch status"
    type = BuildTypeSettings.Type.COMPOSITE

    vcs {
        root(Fork)
        showDependenciesChanges = true
    }

    triggers {
        // The source branch job builds every push to master. The fork's master moves only by fast-forward
        // syncs from upstream.
        vcs {
            branchFilter = "+:<default>"
        }
    }

    // Snapshot (same revision, one chain) only: the composite consumes no files (Lesson 6). Each cell builds
    // from source independently; there is no cross-cell artifact, mirroring buildPlugin()'s parallel cells.
    dependencies {
        snapshot(BuildLinuxJdk25) { onDependencyFailure = FailureAction.ADD_PROBLEM }
        snapshot(BuildWindowsJdk21) { onDependencyFailure = FailureAction.ADD_PROBLEM }
    }
})

// ---------------- PAUSED: source scope deliberately not run live (Lesson 17) ----------------

object LaunchableRecordPaused : BuildType({
    name = "[paused] Launchable: record commit"
    description = "PAUSED. buildPlugin() runs `launchable verify && launchable record commit` on the first cell, using the ci.jenkins.io credential launchable-jenkins-bom (Jenkins-infra only)"
    paused = true

    vcs { root(Fork) }

    params {
        // A declared, empty secure reference. Fill it through the secure-parameter store if this is ever enabled.
        password("env.LAUNCHABLE_TOKEN", "", label = "Launchable token (secure; not provisioned)")
    }

    dependencies {
        snapshot(BuildLinuxJdk25) { onDependencyFailure = FailureAction.CANCEL }
    }

    steps {
        script {
            name = "launchable verify && record commit"
            scriptContent = """
                set -eu
                launchable verify
                launchable record commit
            """.trimIndent()
        }
    }
})

object PublishIncrementalsPaused : BuildType({
    name = "[paused] Publish incrementals"
    description = "PAUSED. buildPlugin() calls infra.maybePublishIncrementals() to repo.jenkins-ci.org/incrementals, with Jenkins-infra-managed credentials and no equivalent here"
    paused = true

    // It needs the first cell's files AND must run on that same revision, so it takes both snapshot and
    // artifact dependencies (Lesson 6).
    dependencies {
        dependency(BuildLinuxJdk25) {
            snapshot { onDependencyFailure = FailureAction.CANCEL }
            artifacts {
                artifactRules = """
                    +:incrementals.zip!** => incrementals
                    +:changelist.txt
                """.trimIndent()
            }
        }
    }

    steps {
        script {
            name = "Publish to incrementals repository (not provisioned)"
            scriptContent = """
                echo "Incrementals publishing is Jenkins-infra-only (maybePublishIncrementals). Not provisioned on this server."
                exit 1
            """.trimIndent()
        }
    }
})

object ContinuousDeliveryPaused : BuildType({
    name = "[paused] Continuous delivery (GHA cd.yaml)"
    description = "PAUSED. GitHub Actions cd.yaml -> jenkins-infra/github-reusable-workflows maven-cd.yml: releases to repo.jenkins-ci.org after the CI check passes. It uses MAVEN_USERNAME/MAVEN_TOKEN, and we have no release rights"
    paused = true

    vcs { root(Fork) }

    params {
        password("env.MAVEN_USERNAME", "", label = "repo.jenkins-ci.org user (secure; not provisioned)")
        password("env.MAVEN_TOKEN", "", label = "repo.jenkins-ci.org token (secure; not provisioned)")
        param("env.JAVA_HOME", "%env.JDK_21_0%")
    }

    requirements {
        equals("teamcity.agent.jvm.os.family", "Linux")
        exists("env.JDK_21_0")
    }

    // cd.yaml triggers on check_run completed, i.e. only after CI passed, so it gets a snapshot dependency
    // on All. maven-cd rebuilds and deploys from source itself, so no artifact dependency is needed.
    dependencies {
        snapshot(All) { onDependencyFailure = FailureAction.CANCEL }
    }

    steps {
        script {
            name = "maven-cd release (not provisioned)"
            scriptContent = """
                echo "maven-cd.yml (JEP-229 CD) is not migrated: it releases to repo.jenkins-ci.org and needs MAVEN_USERNAME/MAVEN_TOKEN."
                exit 1
            """.trimIndent()
        }
    }
})

object SecurityScanPaused : BuildType({
    name = "[paused] Jenkins Security Scan (GHA)"
    description = "PAUSED. GitHub Actions jenkins-security-scan.yml -> jenkins-infra/jenkins-security-scan: CodeQL with a GitHub code-scanning upload (GitHub-native, needs security-events: write)"
    paused = true

    vcs { root(Fork) }

    steps {
        script {
            name = "CodeQL security scan (not provisioned)"
            scriptContent = """
                echo "jenkins-security-scan uploads SARIF to GitHub code scanning; it has no TeamCity equivalent provisioned."
                exit 1
            """.trimIndent()
        }
    }
})
